import { mkdir, readFile, writeFile } from "node:fs/promises";
import path from "node:path";
import { randomUUID } from "node:crypto";

const DATA_DIR = path.join(process.cwd(), "data");
const DB_PATH = path.join(DATA_DIR, "books.json");

async function load() {
  try {
    const books = JSON.parse(await readFile(DB_PATH, "utf8"));
    return Array.isArray(books) ? books : [];
  } catch (err) {
    if (err.code === "ENOENT" || err instanceof SyntaxError) return [];
    throw err;
  }
}

async function save(books) {
  await mkdir(DATA_DIR, { recursive: true });
  await writeFile(DB_PATH, JSON.stringify(books, null, 2) + "\n", "utf8");
}

export async function listBooks() {
  const books = await load();
  return books.sort((a, b) => (a.createdAt < b.createdAt ? 1 : -1));
}

export async function getBook(id) {
  const book = (await load()).find((b) => b.id === id);
  return book ?? null;
}

export async function addBook({ title, author, notes }) {
  const book = {
    id: randomUUID(),
    title: String(title).trim(),
    author: String(author).trim(),
    notes: String(notes ?? "").trim(),
    status: "reading",
    createdAt: new Date().toISOString(),
    finishedAt: null,
  };
  const books = await load();
  books.push(book);
  await save(books);
  return book;
}

export async function updateBook(id, changes) {
  const books = await load();
  const book = books.find((b) => b.id === id);
  if (!book) return null;

  if (typeof changes.title === "string") book.title = changes.title.trim();
  if (typeof changes.author === "string") book.author = changes.author.trim();
  if (typeof changes.notes === "string") book.notes = changes.notes.trim();
  if (changes.status === "finished" || changes.status === "reading") {
    book.status = changes.status;
    book.finishedAt = changes.status === "finished" ? new Date().toISOString() : null;
  }

  await save(books);
  return book;
}

