* {
  box-sizing: border-box;
}

body {
  margin: 0;
  font-family: ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto,
    Helvetica, Arial, sans-serif;
  background: #faf9f7;
  color: #1f2328;
  line-height: 1.5;
}

.wrap {
  max-width: 640px;
  margin: 0 auto;
  padding: 24px 16px 64px;
}

.site-header {
  margin-bottom: 24px;
}

.site-header a {
  font-weight: 700;
  font-size: 1.25rem;
  color: #1f2328;
  text-decoration: none;
}

h1 {
  font-size: 1.4rem;
  margin: 0 0 16px;
}

h2 {
  font-size: 1.05rem;
  margin: 28px 0 8px;
  color: #57606a;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.card {
  background: #fff;
  border: 1px solid #e4e2de;
  border-radius: 10px;
  padding: 16px;
  margin-bottom: 12px;
}

.book-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}

.book-row + .book-row {
  border-top: 1px solid #eeecea;
}

.book-title {
  font-weight: 600;
}

.book-title a {
  color: #1f2328;
  text-decoration: none;
}

.book-title a:hover {
  text-decoration: underline;
}

.book-author {
  color: #57606a;
  font-size: 0.9rem;
}

.empty {
  color: #8b949e;
  font-style: italic;
  margin: 4px 0 12px;
}

form.add-book {
  display: grid;
  gap: 10px;
}

label {
  display: grid;
  gap: 4px;
  font-size: 0.85rem;
  color: #57606a;
}

input,
textarea {
  font: inherit;
  padding: 8px 10px;
  border: 1px solid #d0cdc8;
  border-radius: 8px;
  background: #fff;
}

textarea {
  resize: vertical;
  min-height: 72px;
}

button {
  font: inherit;
  border: none;
  border-radius: 8px;
  padding: 8px 14px;
  cursor: pointer;
  background: #1f2328;
  color: #fff;
}

button:hover {
  background: #3a4148;
}

button.secondary {
  background: #eceae6;
  color: #1f2328;
}

button.secondary:hover {
  background: #dedbd6;
}

button:disabled {
  opacity: 0.6;
  cursor: default;
}

.row-actions {
  display: flex;
  gap: 8px;
}

.badge {
  display: inline-block;
  font-size: 0.75rem;
  padding: 2px 10px;
  border-radius: 999px;
  background: #e8f0e4;
  color: #3c6e3f;
}

.badge.finished {
  background: #e6e9ef;
  color: #4c5a75;
}

.notes {
  white-space: pre-wrap;
  background: #fbfaf8;
  border: 1px solid #eeecea;
  border-radius: 8px;
  padding: 12px;
  margin-top: 8px;
}

.meta {
  color: #8b949e;
  font-size: 0.85rem;
}

.breadcrumbs {
  margin-bottom: 16px;
}

.breadcrumbs a {
  color: #57606a;
  text-decoration: none;
}

.breadcrumbs a:hover {
  text-decoration: underline;
}

.error {
  color: #b3261e;
  font-size: 0.9rem;
}

