import { listBooks } from "../lib/books.js";
import AddBookForm from "../components/add-book-form.jsx";
import BookRow from "../components/book-row.jsx";

export const dynamic = "force-dynamic";

export default async function HomePage() {
  const books = await listBooks();
  const reading = books.filter((b) => b.status === "reading");
  const finished = books.filter((b) => b.status === "finished");

  return (
    <>
      <h1>My Books</h1>

      <section className="card">
        <AddBookForm />
      </section>

      <h2>Currently reading</h2>
      {reading.length === 0 ? (
        <p className="empty">Nothing here yet. Add a book above.</p>
      ) : (
        <section className="card">
          {reading.map((book) => (
            <BookRow key={book.id} book={book} />
          ))}
        </section>
      )}

      <h2>Finished</h2>
      {finished.length === 0 ? (
        <p className="empty">No finished books yet.</p>
      ) : (
        <section className="card">
          {finished.map((book) => (
            <BookRow key={book.id} book={book} />
          ))}
        </section>
      )}
    </>
  );
}

