"use client";

import { useState } from "react";
import { useRouter } from "next/navigation";

export default function AddBookForm() {
  const router = useRouter();
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState("");

  async function onSubmit(e) {
    e.preventDefault();
    const form = e.currentTarget;
    const data = new FormData(form);
    setSaving(true);
    setError("");
    const res = await fetch("/api/books", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        title: data.get("title"),
        author: data.get("author"),
        notes: data.get("notes"),
      }),
    });
    setSaving(false);
    if (!res.ok) {
      setError((await res.json().catch(() => ({}))).error ?? "Could not add book.");
      return;
    }
    form.reset();
    router.refresh();
  }

  return (
    <form className="add-book" onSubmit={onSubmit}>
      <label>
        Title
        <input name="title" required placeholder="The Left Hand of Darkness" />
      </label>
      <label>
        Author
        <input name="author" required placeholder="Ursula K. Le Guin" />
      </label>
      <label>
        Notes (optional)
        <textarea name="notes" placeholder="Why you're reading it, where you stopped..." />
      </label>
      {error && <p className="error">{error}</p>}
      <div>
        <button type="submit" disabled={saving}>
          {saving ? "Adding..." : "Add book"}
        </button>
      </div>
    </form>
  );
}

